export {
  filledTrackClasses as baseUiSliderFilledTrackClasses,
  headerClasses as baseUiSliderHeaderClasses,
  labelClasses as baseUiSliderLabelClasses,
  rootClasses as baseUiSliderRootClasses,
  sliderFieldView as baseUiSliderFieldView,
  thumbClasses as baseUiSliderThumbClasses,
  trackClasses as baseUiSliderTrackClasses,
  valueClasses as baseUiSliderValueClasses,
} from "../../../foldkit/ui/slider/view";
export type { SliderFieldViewInput as BaseUiSliderFieldViewInput } from "../../../foldkit/ui/slider/view";

import { describe, expect, test } from "vitest";

import * as Slider from "./index";

describe("Base UI Slider registry view", () => {
  test("reuses the Foldkit Slider functional contract", () => {
    expect(Slider.init).toBeTypeOf("function");
    expect(Slider.update).toBeTypeOf("function");
    expect(Slider.view).toBeTypeOf("function");
    expect(Slider.baseUiSliderRootClasses).toContain("relative");
  });
});
